    idempotency_key text NOT NULL COLLATE pg_catalog."C",
    request_hash bytea NOT NULL,
    resource_type text NOT NULL,
    resource_id text NOT NULL COLLATE pg_catalog."C",
    http_status smallint NOT NULL,
    response_body jsonb,
    response_headers jsonb,
    response_hash bytea NOT NULL,
    correlation_id text NOT NULL COLLATE pg_catalog."C",
    credential_id text NOT NULL COLLATE pg_catalog."C",
    committed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    replay_expires_at timestamp with time zone NOT NULL,
    tombstoned_at timestamp with time zone,
    CONSTRAINT idempotency_records_command_type CHECK ((command_type = ANY (ARRAY['CREATE_PAYMENT'::text, 'AUTHORIZE'::text, 'CAPTURE'::text, 'CANCEL'::text, 'REFUND'::text]))),
    CONSTRAINT idempotency_records_correlation_id CHECK ((correlation_id ~ '^[A-Za-z0-9._:-]{16,128}$'::text)),
    CONSTRAINT idempotency_records_http_status CHECK (((http_status = ANY (ARRAY[201, 202])) AND ((http_status = 201) = (command_type = 'CREATE_PAYMENT'::text)))),
    CONSTRAINT idempotency_records_key_format CHECK ((idempotency_key ~ '^[A-Za-z0-9._:-]{16,128}$'::text)),
    CONSTRAINT idempotency_records_replay_shape CHECK ((((tombstoned_at IS NULL) AND (response_body IS NOT NULL) AND (response_headers IS NOT NULL) AND (jsonb_typeof(response_body) = 'object'::text) AND (jsonb_typeof(response_headers) = 'object'::text)) OR ((tombstoned_at IS NOT NULL) AND (response_body IS NULL) AND (response_headers IS NULL)))),
    CONSTRAINT idempotency_records_replay_window CHECK ((replay_expires_at = (committed_at + '90 days'::interval))),
    CONSTRAINT idempotency_records_request_hash CHECK (public.fl_is_sha256(request_hash)),
    CONSTRAINT idempotency_records_resource_id_format CHECK (
CASE resource_type
    WHEN 'PAYMENT'::text THEN public.fl_is_id(resource_id, 'pay'::text)
    ELSE public.fl_is_id(resource_id, 'op'::text)
END),
    CONSTRAINT idempotency_records_resource_type CHECK ((((resource_type = 'PAYMENT'::text) = (command_type = 'CREATE_PAYMENT'::text)) AND (resource_type = ANY (ARRAY['PAYMENT'::text, 'PAYMENT_OPERATION'::text])))),
    CONSTRAINT idempotency_records_response_hash CHECK (public.fl_is_sha256(response_hash))
);


