    CONSTRAINT fee_policies_minimum_capture_max CHECK ((minimum_capture_amount_minor <= '1000000000000'::bigint)),
    CONSTRAINT fee_policies_refund_fee_mode CHECK ((refund_fee_mode = 'PROPORTIONAL'::text)),
    CONSTRAINT fee_policies_version_positive CHECK ((version > 0))
);


--
-- Name: payment_operations; Type: TABLE; Schema: payments; Owner: -
--

CREATE TABLE payments.payment_operations (
    id text NOT NULL COLLATE pg_catalog."C",
    merchant_id text NOT NULL COLLATE pg_catalog."C",
    payment_id text NOT NULL COLLATE pg_catalog."C",
    type text NOT NULL,
    amount_minor bigint NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    status text DEFAULT 'REQUESTED'::text NOT NULL,
    provider_account_id text NOT NULL COLLATE pg_catalog."C",
    provider_account_version integer NOT NULL,
    provider_idempotency_key text NOT NULL COLLATE pg_catalog."C",
    provider_operation_id text,
    capture_operation_id text COLLATE pg_catalog."C",
    fee_policy_id text COLLATE pg_catalog."C",
    fee_policy_version integer,
    fee_basis_points integer,
    fee_fixed_amount_minor bigint,
    fee_capture_rounding_mode text,
    fee_refund_mode text,
    fee_effect_type text DEFAULT 'NONE'::text NOT NULL,
    fee_effect_amount_minor bigint,
    result_code text,
    resolution_source text,
    resolution_evidence_id text COLLATE pg_catalog."C",
    processing_started_at timestamp with time zone,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    not_before timestamp with time zone,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    resolved_at timestamp with time zone,
    CONSTRAINT payment_operations_amount CHECK (((amount_minor >= 1) AND (amount_minor <= '1000000000000'::bigint))),
    CONSTRAINT payment_operations_currency CHECK ((currency = 'USD'::text)),
    CONSTRAINT payment_operations_fee_effect CHECK (
CASE type
    WHEN 'CAPTURE'::text THEN ((fee_effect_type = 'CHARGE'::text) AND (fee_effect_amount_minor IS NOT NULL) AND ((fee_effect_amount_minor >= 0) AND (fee_effect_amount_minor <= amount_minor)))
    WHEN 'REFUND'::text THEN ((fee_effect_type = 'REFUND'::text) AND (((status = 'SUCCEEDED'::text) AND (fee_effect_amount_minor IS NOT NULL) AND (fee_effect_amount_minor >= 0)) OR ((status <> 'SUCCEEDED'::text) AND (fee_effect_amount_minor IS NULL))))
    ELSE ((fee_effect_type = 'NONE'::text) AND (fee_effect_amount_minor IS NULL))
END),
    CONSTRAINT payment_operations_fee_snapshot CHECK (
CASE
    WHEN (type = ANY (ARRAY['CAPTURE'::text, 'REFUND'::text])) THEN ((fee_policy_id IS NOT NULL) AND (fee_policy_version IS NOT NULL) AND (fee_basis_points IS NOT NULL) AND (fee_fixed_amount_minor IS NOT NULL) AND (fee_capture_rounding_mode IS NOT NULL) AND (fee_refund_mode IS NOT NULL))
    ELSE ((fee_policy_id IS NULL) AND (fee_policy_version IS NULL) AND (fee_basis_points IS NULL) AND (fee_fixed_amount_minor IS NULL) AND (fee_capture_rounding_mode IS NULL) AND (fee_refund_mode IS NULL))
END),
    CONSTRAINT payment_operations_fee_snapshot_values CHECK ((((fee_basis_points IS NULL) OR ((fee_basis_points >= 0) AND (fee_basis_points <= 10000))) AND ((fee_fixed_amount_minor IS NULL) OR ((fee_fixed_amount_minor >= 0) AND (fee_fixed_amount_minor <= '1000000000000'::bigint))) AND ((fee_capture_rounding_mode IS NULL) OR (fee_capture_rounding_mode = 'HALF_UP'::text)) AND ((fee_refund_mode IS NULL) OR (fee_refund_mode = 'PROPORTIONAL'::text)))),
    CONSTRAINT payment_operations_id_format CHECK (public.fl_is_id(id, 'op'::text)),
    CONSTRAINT payment_operations_not_before CHECK (((not_before IS NULL) OR (status = 'REQUESTED'::text))),
    CONSTRAINT payment_operations_provider_key_nonempty CHECK (((char_length(provider_idempotency_key) >= 1) AND (char_length(provider_idempotency_key) <= 255))),
    CONSTRAINT payment_operations_refund_capture_link CHECK (((type = 'REFUND'::text) = (capture_operation_id IS NOT NULL))),
    CONSTRAINT payment_operations_resolution CHECK ((((status = ANY (ARRAY['SUCCEEDED'::text, 'REJECTED'::text, 'FAILED'::text])) = (resolution_evidence_id IS NOT NULL)) AND ((resolution_evidence_id IS NULL) = (resolution_source IS NULL)))),
    CONSTRAINT payment_operations_resolution_evidence_format CHECK (((resolution_evidence_id IS NULL) OR public.fl_is_id(resolution_evidence_id, 'pev'::text))),
    CONSTRAINT payment_operations_resolution_source CHECK (((resolution_source IS NULL) OR (resolution_source = ANY (ARRAY['API_RESPONSE'::text, 'PROVIDER_WEBHOOK'::text, 'RECONCILIATION'::text])))),
    CONSTRAINT payment_operations_resolved_at CHECK (((status = ANY (ARRAY['SUCCEEDED'::text, 'REJECTED'::text, 'FAILED'::text])) = (resolved_at IS NOT NULL))),
    CONSTRAINT payment_operations_result_code CHECK ((((status = ANY (ARRAY['REJECTED'::text, 'FAILED'::text])) = (result_code IS NOT NULL)) AND ((result_code IS NULL) OR (result_code ~ '^[A-Z][A-Z0-9_]{0,63}$'::text)))),
    CONSTRAINT payment_operations_status CHECK ((status = ANY (ARRAY['REQUESTED'::text, 'PROCESSING'::text, 'SUCCEEDED'::text, 'REJECTED'::text, 'FAILED'::text, 'UNKNOWN'::text, 'REQUIRES_REVIEW'::text]))),
    CONSTRAINT payment_operations_success_reference CHECK (((status <> 'SUCCEEDED'::text) OR ((provider_operation_id IS NOT NULL) AND (result_code IS NULL)))),
    CONSTRAINT payment_operations_type CHECK ((type = ANY (ARRAY['AUTHORIZE'::text, 'CAPTURE'::text, 'CANCEL'::text, 'REFUND'::text]))),
    CONSTRAINT payment_operations_version_positive CHECK ((version >= 1))
);


--
-- Name: payments; Type: TABLE; Schema: payments; Owner: -
--

CREATE TABLE payments.payments (
    id text NOT NULL COLLATE pg_catalog."C",
    merchant_id text NOT NULL COLLATE pg_catalog."C",
    merchant_reference text,
    currency text DEFAULT 'USD'::text NOT NULL,
    payment_method_reference_ciphertext bytea NOT NULL,
    payment_method_key_version text NOT NULL,
    payment_method_reference_hash bytea NOT NULL,
    provider_account_id text NOT NULL COLLATE pg_catalog."C",
    provider_account_version integer NOT NULL,
    provider_payment_id text,
    provider_authorization_id text,
    provider_capture_id text,
    fee_policy_id text NOT NULL COLLATE pg_catalog."C",
    fee_policy_version integer NOT NULL,
    requested_amount_minor bigint NOT NULL,
    authorized_amount_minor bigint DEFAULT 0 NOT NULL,
    captured_amount_minor bigint DEFAULT 0 NOT NULL,
    refunded_amount_minor bigint DEFAULT 0 NOT NULL,
    voided_amount_minor bigint DEFAULT 0 NOT NULL,
    reserved_refund_amount_minor bigint DEFAULT 0 NOT NULL,
    unresolved_refund_count integer DEFAULT 0 NOT NULL,
    authorization_outcome text DEFAULT 'NOT_REQUESTED'::text NOT NULL,
    active_exclusive_operation_id text COLLATE pg_catalog."C",
    version bigint DEFAULT 1 NOT NULL,
    created_by_credential_id text COLLATE pg_catalog."C",
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT payments_active_operation_format CHECK (((active_exclusive_operation_id IS NULL) OR public.fl_is_id(active_exclusive_operation_id, 'op'::text))),
    CONSTRAINT payments_authorization_outcome CHECK ((authorization_outcome = ANY (ARRAY['NOT_REQUESTED'::text, 'AUTHORIZED'::text, 'DECLINED'::text, 'CANCELED'::text, 'EXPIRED'::text]))),
    CONSTRAINT payments_authorized_le_requested CHECK ((authorized_amount_minor <= requested_amount_minor)),
    CONSTRAINT payments_capture_releases_remainder CHECK (((captured_amount_minor = 0) OR ((captured_amount_minor + voided_amount_minor) = authorized_amount_minor))),
    CONSTRAINT payments_captured_le_authorized CHECK ((captured_amount_minor <= authorized_amount_minor)),
    CONSTRAINT payments_currency CHECK ((currency = 'USD'::text)),
    CONSTRAINT payments_exclusive_excludes_refunds CHECK (((active_exclusive_operation_id IS NULL) OR (unresolved_refund_count = 0))),
    CONSTRAINT payments_id_format CHECK (public.fl_is_id(id, 'pay'::text)),
    CONSTRAINT payments_merchant_reference_length CHECK (((merchant_reference IS NULL) OR ((char_length(merchant_reference) >= 1) AND (char_length(merchant_reference) <= 200)))),
    CONSTRAINT payments_payment_method_ciphertext CHECK ((octet_length(payment_method_reference_ciphertext) > 0)),
    CONSTRAINT payments_payment_method_hash CHECK (public.fl_is_sha256(payment_method_reference_hash)),
    CONSTRAINT payments_payment_method_key_version CHECK ((char_length(payment_method_key_version) > 0)),
    CONSTRAINT payments_provider_refs_nonempty CHECK (((COALESCE(char_length(provider_payment_id), 1) > 0) AND (COALESCE(char_length(provider_authorization_id), 1) > 0) AND (COALESCE(char_length(provider_capture_id), 1) > 0))),
    CONSTRAINT payments_refund_reservation_bound CHECK (((refunded_amount_minor + reserved_refund_amount_minor) <= captured_amount_minor)),
    CONSTRAINT payments_refunded_le_captured CHECK ((refunded_amount_minor <= captured_amount_minor)),
    CONSTRAINT payments_released_authorization CHECK (((authorization_outcome <> ALL (ARRAY['CANCELED'::text, 'EXPIRED'::text])) OR ((captured_amount_minor = 0) AND (refunded_amount_minor = 0) AND (voided_amount_minor = authorized_amount_minor)))),
    CONSTRAINT payments_requested_amount CHECK (((requested_amount_minor >= 1) AND (requested_amount_minor <= '1000000000000'::bigint))),
    CONSTRAINT payments_reservation_count CHECK (((reserved_refund_amount_minor = 0) = (unresolved_refund_count = 0))),
    CONSTRAINT payments_totals_nonnegative CHECK (((authorized_amount_minor >= 0) AND (captured_amount_minor >= 0) AND (refunded_amount_minor >= 0) AND (voided_amount_minor >= 0) AND (reserved_refund_amount_minor >= 0) AND (unresolved_refund_count >= 0))),
    CONSTRAINT payments_unauthorized_zero CHECK (((authorization_outcome <> ALL (ARRAY['NOT_REQUESTED'::text, 'DECLINED'::text])) OR ((authorized_amount_minor = 0) AND (captured_amount_minor = 0) AND (refunded_amount_minor = 0) AND (voided_amount_minor = 0)))),
    CONSTRAINT payments_version_positive CHECK ((version >= 1)),
    CONSTRAINT payments_voided_le_uncaptured CHECK ((voided_amount_minor <= (authorized_amount_minor - captured_amount_minor)))
);


